# -*- coding: utf-8 -*-
"""
sitecustomize.py —— 套壳运行时的 Android 适配层（不修改用户项目代码）

1) 预加载 SDL2 系列库（RTLD_GLOBAL），保证 pygame 扩展 dlopen libSDL2.so 时
   能解析依赖（jniLibs 里的库通常已被 linker 自动解析，这里做双保险）。
2) 热更新适配：Android 嵌入式 Python 没有 python 可执行文件，
   updater.restart_game() 的 os.execv 必然失败；这里把 os.execv 替换为
   提示“请手动重启 App”（更新文件已应用，重启后生效），避免游戏崩溃。
3) ssl CA 适配：Android 上没有 /etc/ssl/certs，把默认 CA 指向系统 CA 目录，
   保证 urllib https 请求（GitHub 更新检查）能通过证书验证。
"""

import os
import sys
import ctypes
import traceback


def _log(msg):
    try:
        print("[android] " + msg, file=sys.stderr)
        sys.stderr.flush()
    except Exception:
        pass


def _is_android():
    return os.environ.get("ANDROID_ROOT") or hasattr(sys, "getandroidapilevel")


if _is_android():
    # ---- 0) import 追踪：native 崩溃时定位最后成功加载的模块 ----
    # 注意：必须改 builtins.__import__，改局部 __import__ 名字不生效
    try:
        import builtins
        _trace_path = None
        _files_base = os.environ.get("PYTHON_ANDROID_FILES")
        if _files_base:
            _trace_path = os.path.join(_files_base, "import_trace.txt")
            try:
                with open(_trace_path, "w") as _f:
                    _f.write("sitecustomize loaded\n")
            except Exception:
                _trace_path = None
        _orig_import = builtins.__import__

        def _trace_import(name, *args, **kwargs):
            if _trace_path:
                try:
                    with open(_trace_path, "a") as _f:
                        _f.write("import " + str(name) + "\n")
                except Exception:
                    pass
            return _orig_import(name, *args, **kwargs)

        builtins.__import__ = _trace_import
    except Exception:
        pass

    # ---- 0.5) 【已移除】不再在 sitecustomize 阶段 import pygame ----
    # 过早加载 pygame 扩展会在 Py_Initialize 的 import site 阶段引发 native
    # 崩溃（stage 停在 python init），改为由游戏代码自身在合适时机加载。
    # pygame 调用追踪改由 bridge 层注入（见 python_bridge.cpp bootstrap）。

    # ---- 1) libpython + SDL 库 RTLD_GLOBAL 预加载 ----
    # 关键：pygame 扩展的 DT_NEEDED 里没有 libpython，靠全局符号表解析
    # PyExc_RuntimeError 等 Python API。必须在 import pygame 之前把
    # libpython3.14.so 以 RTLD_GLOBAL 加载（完整路径，bionic namespace 下
    # 相对名可能找不到）。已被 python_bridge 以 LOCAL 加载的 libpython，
    # 再次以 GLOBAL dlopen 会被 bionic 提升符号可见性。
    try:
        _native_lib = os.environ.get("ANDROID_NATIVE_LIB_DIR", "")
        _preload_libs = [
            "libpython3.14.so",
            "libSDL2.so",
            "libSDL2_image.so",
            "libSDL2_mixer.so",
            "libSDL2_ttf.so",
            "libfreetype.so",
            "libcrypto_python.so",
            "libssl_python.so",
        ]
        for _name in _preload_libs:
            _path = os.path.join(_native_lib, _name) if _native_lib else _name
            try:
                ctypes.CDLL(_path, mode=ctypes.RTLD_GLOBAL)
                _log("RTLD_GLOBAL loaded: " + _name)
            except Exception:
                try:
                    ctypes.CDLL(_name, mode=ctypes.RTLD_GLOBAL)
                except Exception:
                    _log("RTLD_GLOBAL FAILED: " + _name)
    except Exception:
        pass

    # ---- 2) 热更新重启适配：os.execv ----
    _real_execv = os.execv

    def _android_execv(path, args, env=None):
        _log("热更新已完成文件替换，但 Android 嵌入式 Python 没有可执行文件，"
             "无法自动重启进程。请手动关闭并重新打开 App，新版本即可生效。")
        return

    os.execv = _android_execv

    # ---- 3) ssl 默认 CA 指向 Android 系统 CA ----
    try:
        import ssl

        _android_ca_dirs = [
            "/apex/com.android.conscrypt/cacerts",
            "/system/etc/security/cacerts",
        ]
        _real_create_default_context = ssl.create_default_context

        def _create_default_context(*args, **kwargs):
            ctx = _real_create_default_context(*args, **kwargs)
            # 两个 CA 目录都加载，不能 break：
            # /apex/com.android.conscrypt/cacerts 在 Android 10 上存在但内容
            # 可能不全/格式异常，若只加载它而跳过 /system/etc/security/cacerts，
            # store 会缺签发 CA -> unable to get local issuer certificate。
            for p in _android_ca_dirs:
                if os.path.isdir(p):
                    try:
                        ctx.load_verify_locations(capath=p)
                        _log("ssl capath loaded: " + p)
                    except Exception as e:
                        _log("ssl capath FAIL " + p + ": " + repr(e))
            # 补充打包的 Let's Encrypt 新根证书：
            # gh-proxy.com 等 2026 年站点用 ISRG Root X2 新链，而 Android 10
            # （2020 年出厂）系统 CA 只有 ISRG Root X1，没有 X2 信任锚 ->
            # unable to get local issuer certificate。cafile 显式补锚。
            _certs_dir = os.path.join(sys.prefix, "certs")
            for f in ("isrg-root-x1.pem", "isrg-root-x2.pem"):
                fp = os.path.join(_certs_dir, f)
                if os.path.isfile(fp):
                    try:
                        ctx.load_verify_locations(cafile=fp)
                        _log("ssl cafile loaded: " + fp)
                    except Exception as e:
                        _log("ssl cafile FAIL " + fp + ": " + repr(e))
                else:
                    _log("ssl certs MISSING (prefix=" + sys.prefix + "): " + fp)
            return ctx

        ssl.create_default_context = _create_default_context
        # urllib.request 用的是 ssl._create_default_https_context 别名，
        # 只 patch create_default_context 对 urllib 无效，必须一并替换。
        if hasattr(ssl, "_create_default_https_context"):
            ssl._create_default_https_context = _create_default_context
            _log("ssl._create_default_https_context patched")
        # 环境变量兜底（bridge 层已在 C 侧 setenv，这里再保险一次）。
        # SSL_CERT_DIR 只能指一个目录，优先选确定有效的系统 CA 目录。
        for p in ["/system/etc/security/cacerts", "/apex/com.android.conscrypt/cacerts"]:
            if os.path.isdir(p):
                os.environ["SSL_CERT_DIR"] = p
                _log("ssl SSL_CERT_DIR=" + p)
                break
    except Exception as e:
        _log("ssl setup FAIL: " + repr(e))

    # ---- 4) pygame 字体：Android 沙箱无 fc-list（fontconfig）且禁止 exec，
    #          pygame.sysfont 扫系统字体时 subprocess.run('fc-list') 抛
    #          PermissionError -> 游戏退出。patch 使其静默返回空字典，
    #          找不到名字时 SysFont 自动回退默认字体，游戏自带的
    #          assets/fonts/custom.ttf 不受影响。 ----
    try:
        import pygame.sysfont
        _orig_initsysfonts_unix = pygame.sysfont.initsysfonts_unix
        def _initsysfonts_unix(*a, **k):
            try:
                return _orig_initsysfonts_unix(*a, **k)
            except Exception as e:
                _log("pygame sysfont fc-list unavailable, using defaults: " + repr(e))
                return {}
        pygame.sysfont.initsysfonts_unix = _initsysfonts_unix
        _log("pygame sysfont patched (no fc-list)")
    except Exception as e:
        _log("pygame sysfont patch FAIL: " + repr(e))

    # ---- 5) pygame 字体渲染：游戏渲染更新日志(changelog)时空行 ->
    #          pygame.error: Text has zero width -> 游戏退出。
    #          兜底：空文本返回 1px 透明 surface；渲染异常同样兜底。 ----
    try:
        import pygame
        _orig_font_render = pygame.font.Font.render
        def _safe_font_render(self, text, antialias, color, *args, **kwargs):
            if not text:
                return pygame.Surface((1, self.get_height()), pygame.SRCALPHA)
            try:
                return _orig_font_render(self, text, antialias, color, *args, **kwargs)
            except pygame.error as e:
                _log("pygame render fallback (zero width): " + repr(e))
                return pygame.Surface((1, self.get_height()), pygame.SRCALPHA)
        pygame.font.Font.render = _safe_font_render
        _log("pygame font.render patched (empty-text safe)")
    except Exception as e:
        _log("pygame render patch FAIL: " + repr(e))

    # ---- 6) PyOpenGL 平台适配：Android 没有桌面 libGL.so，只有 GLES。
    #          PyOpenGL 的 _loadLibraryPosix 硬编码试 lib{name}.so，
    #          加载失败时回退到 libGLESv2.so / libEGL.so（系统库，bootstrap
    #          已 RTLD_GLOBAL 预加载）。
    #          注意：桌面 OpenGL API（glBegin 等）在 GLES 不存在，
    #          项目需使用 OpenGL.GLES2 / OpenGL.EGL 编写，或使用 ModernGL。 ----
    try:
        import OpenGL.platform.ctypesloader as _ocl
        _orig_load_posix = _ocl._loadLibraryPosix
        _gles_fallback = {
            'GL': 'libGLESv2.so',
            'GLESv2': 'libGLESv2.so',
            'GLESv1_CM': 'libGLESv1_CM.so',
            'EGL': 'libEGL.so',
        }
        def _load_lib_posix(dllType, name, mode):
            try:
                return _orig_load_posix(dllType, name, mode)
            except Exception as _e:
                if name in _gles_fallback:
                    _log("OpenGL fallback: %s -> %s" % (name, _gles_fallback[name]))
                    return dllType(_gles_fallback[name], mode)
                raise
        _ocl._loadLibraryPosix = _load_lib_posix
        _log("OpenGL platform patched (GL->GLES fallback)")
    except Exception as e:
        _log("OpenGL platform patch FAIL: " + repr(e))

    # ---- 7) ModernGL：Android 只有 GLES（version_code=300~320），而
    #          create_context() 默认 require=330（桌面 GL3.3）-> ValueError。
    #          放宽 require 到 300；standalone 强制用 SDL 已建好的当前 context。
    #          （glcontext 包不内置：moderngl 非 standalone 路径不依赖它） ----
    try:
        import moderngl
        _orig_mg_create = moderngl.create_context
        def _mg_create_context(require=None, standalone=False, share=False, **settings):
            if require is None or require > 330:
                _log("ModernGL require %s -> 300 (GLES)" % (require,))
                require = 300
            if standalone:
                _log("ModernGL standalone -> use current SDL context")
                standalone = False
            return _orig_mg_create(require=require, standalone=standalone,
                                   share=share, **settings)
        moderngl.create_context = _mg_create_context
        _log("ModernGL patched (require=300, GLES)")
    except Exception as e:
        _log("ModernGL patch skip: " + repr(e))
